y\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/kingcharleslzy-ai/dsh-purge.git\"\n  },\n  \"homepage\": \"https://github.com/kingcharleslzy-ai/dsh-purge#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/kingcharleslzy-ai/dsh-purge/issues\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-sidebar-right\"\n      ]\n    },\n    \"install\": {\n      \"preferred\": \"tarball\",\n      \"tarball\": \"https://github.com/kingcharleslzy-ai/dsh-purge/releases/latest/download/dsh-purge-community-1.6.60.tgz\",\n      \"git\": \"https://github.com/kingcharleslzy-ai/dsh-purge.git\"\n    }\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\"\n  },\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"dshTarget\": \"0.2.1-rc.1 (runtime injection + host patches verified)\",\n  \"contributors\": [\n    \"小杨 / YuJunZhiXue (original dsh-purge author)\",\n    {\n      \"name\": \"luowang-ui\",\n      \"url\": \"https://github.com/luowang-ui\"\n    },\n    {\n      \"name\": \"heigit\",\n      \"url\": \"https://github.com/heigit\"\n    },\n    {\n      \"name\": \"OGHong\",\n      \"url\": \"https://github.com/OGHong\"\n    },\n    {\n      \"name\": \"loLollipop\",\n      \"url\": \"https://github.com/loLollipop\"\n    },\n    {\n      \"name\": \"youki258\",\n      \"url\": \"https://github.com/youki258\"\n    },\n    {\n      \"name\": \"SimonQvQ\",\n      \"url\": \"https://github.com/SimonQvQ\"\n    }\n  ],\n  \"author\": {\n    \"name\": \"kingcharleslzy-ai\",\n    \"url\": \"https://github.com